/*
 * nes-pi - TV filter: blargg's nes_ntsc (LGPL 2.1+, in third_party/nestopia/
 * nes_ntsc, copied by build.sh into the build directory) with nes-pi's own
 * configuration: the PPU's 9-bit palette indices (emphasis included) in,
 * 0x00RRGGBB out, one line at a time. The colours are generated by the
 * filter from the NES signal, as on a real TV (no RGB palette in).
 */
#define NES_NTSC_EMPHASIS	1
#define NES_NTSC_OUT_DEPTH	32
#define NES_NTSC_IN_T		unsigned short
#define NES_NTSC_ADJ_IN(in)	((in) & 0x1FF)
#define NES_NTSC_CONFIG_H	/* the library's own configuration file is not used */

/* The library keeps its tables as unsigned long: 64 bits on the Pi, twice the
   memory (and cache) its 32-bit arithmetic needs. Compiled with long = int
   it gives exactly the same pixels (checked line by line) with half the
   tables. The system headers it uses come first, untouched. */
#include <assert.h>
#include <math.h>
#include <limits.h>
#define long int
#include "nst/nes_ntsc/nes_ntsc.h"
#include "nst/nes_ntsc/nes_ntsc.inl"
#undef long

#include "ntsc_blargg.h"

static nes_ntsc_t s_Ntsc;

void ntsc_blargg_setup (int nMode)
{
	nes_ntsc_setup_t Setup = nMode == NTSC_SVIDEO ? nes_ntsc_svideo : nes_ntsc_composite;
	if (nMode == NTSC_RF)
	{
		/* "grandma's TV": blargg's own controls, every defect at its limit */
		Setup.artifacts  =  1.0;	/* colour artifacts from colour changes */
		Setup.fringing   =  1.0;	/* colour fringes from brightness changes */
		Setup.bleed      =  1.0;	/* colour bleeding */
		Setup.sharpness  = -1.0;	/* blurred edges */
		Setup.resolution = -1.0;	/* least detail */
	}
	Setup.merge_fields = 0;		/* the real thing: artifacts crawl and shimmer */
	Setup.palette = 0;		/* colours from the NES signal model */
	Setup.base_palette = 0;
	nes_ntsc_init (&s_Ntsc, &Setup);
}

void ntsc_blargg_line (const unsigned short *pIn, unsigned nPhase, unsigned *pOut)
{
	nes_ntsc_blit (&s_Ntsc, pIn, NTSC_IN_W, nPhase % 3, NTSC_IN_W, 1, pOut, NTSC_OUT_W * 4);
}
